const menu=document.querySelector('.menu'),nav=document.querySelector('#navegacion');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Cerrar':'Menú';nav.classList.toggle('open',open)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menú';menu.focus()}});
const readings=[{name:'PLAN BÁSICO',title:'Lidera la elección ilustrativa. Falta entender por qué.',evidence:'El 42% supera por 7 puntos porcentuales al plan con asistencia y por 19 al configurable.',question:'¿La elección responde al precio, a la claridad de la oferta o a los beneficios incluidos? Esta distribución por sí sola no lo explica.',next:'Contrastar razones de elección y diferencias por perfil, y revisar costos y viabilidad antes de priorizar una prueba de mercado.'},{name:'PLAN CON ASISTENCIA',title:'La segunda posición no descarta una oportunidad.',evidence:'El 35% queda a 7 puntos porcentuales del plan básico y a 12 del configurable.',question:'¿Para qué perfiles tiene valor la asistencia y bajo qué condiciones? El total no permite identificar a esos grupos.',next:'Examinar diferencias por perfil y evidencia sobre el valor de la asistencia. No atribuir su elección a un solo beneficio sin analizarlo.'},{name:'PLAN CONFIGURABLE',title:'Una proporción menor también requiere contexto.',evidence:'El 23% queda a 19 puntos porcentuales del plan básico y a 12 del plan con asistencia.',question:'¿Existe un grupo con necesidades específicas o la propuesta resulta difícil de comprender? Son hipótesis que requieren evidencia.',next:'Revisar comprensión, necesidades y viabilidad. Una proporción agregada menor no basta para decidir retirar la propuesta.'}];
document.querySelectorAll('[data-offer]').forEach(button=>button.addEventListener('click',()=>{const index=Number(button.dataset.offer);document.querySelectorAll('[data-offer]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.offer)===index)));document.querySelectorAll('[data-reading]').forEach(element=>{element.textContent=readings[index][element.dataset.reading]})}));
